import{_ as a,o,c as r,a2 as t}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"Class: Logger","description":"","frontmatter":{},"headers":[],"relativePath":"api/twine/classes/Logger.md","filePath":"api/twine/classes/Logger.md"}'),s={name:"api/twine/classes/Logger.md"};function c(n,e,d,i,l,h){return o(),r("div",null,[...e[0]||(e[0]=[t('<p><a href="./../">twine</a> / Logger</p><h1 id="class-logger" tabindex="-1">Class: Logger <a class="header-anchor" href="#class-logger" aria-label="Permalink to &quot;Class: Logger&quot;">​</a></h1><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/1f7cf8c4b76144202afb9534cfbe54d591828868/twine/src/logger.ts#L39" target="_blank" rel="noreferrer">logger.ts:39</a></p><p>A per-player, severity-threshold logger: each player has their own score on one objective (unset = logging off for them), set via the generated <code>debug/log/{debug,info,warn,off}</code> functions. A message at level <code>L</code> reaches exactly the players whose score is <code>&lt;= SEVERITY[L]</code> - so a player who sets themselves to <code>debug</code> sees everything, <code>warn</code> sees only warnings, and a player who never runs any of these commands sees nothing.</p><p>Unlike a per-namespace on/off flag, the namespace passed to <a href="#for-1">for</a> is only a label in the message - it does not gate anything - so it needs no name to be reserved ahead of time and costs no extra scoreboard entry.</p><p><code>TWINE_LOG=off</code> is a build-time kill switch: it makes every emitted message a true no-op (no commands at all), rather than one gated by a check that always fails.</p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to &quot;Constructors&quot;">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to &quot;Constructor&quot;">​</a></h3><blockquote><p><strong>new Logger</strong>(<code>dp</code>, <code>objectiveName?</code>): <code>Logger</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/1f7cf8c4b76144202afb9534cfbe54d591828868/twine/src/logger.ts#L46" target="_blank" rel="noreferrer">logger.ts:46</a></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="dp" tabindex="-1">dp <a class="header-anchor" href="#dp" aria-label="Permalink to &quot;dp&quot;">​</a></h5><p><code>Datapack</code></p><h5 id="objectivename" tabindex="-1">objectiveName? <a class="header-anchor" href="#objectivename" aria-label="Permalink to &quot;objectiveName?&quot;">​</a></h5><p><code>string</code> = <code>&quot;LogLevel&quot;</code></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>Logger</code></p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="for" tabindex="-1">for() <a class="header-anchor" href="#for" aria-label="Permalink to &quot;for()&quot;">​</a></h3><blockquote><p><strong>for</strong>(<code>namespace</code>): <a href="./../interfaces/NamespaceLogger.html"><code>NamespaceLogger</code></a></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/1f7cf8c4b76144202afb9534cfbe54d591828868/twine/src/logger.ts#L76" target="_blank" rel="noreferrer">logger.ts:76</a></p><p>Instance form of <a href="#for-1">Logger.for</a>, for callers already holding a <code>Logger</code>.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="namespace" tabindex="-1">namespace <a class="header-anchor" href="#namespace" aria-label="Permalink to &quot;namespace&quot;">​</a></h5><p><code>string</code></p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><a href="./../interfaces/NamespaceLogger.html"><code>NamespaceLogger</code></a></p><hr><h3 id="registercommands" tabindex="-1">registerCommands() <a class="header-anchor" href="#registercommands" aria-label="Permalink to &quot;registerCommands()&quot;">​</a></h3><blockquote><p><strong>registerCommands</strong>(<code>dp</code>, <code>path?</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/1f7cf8c4b76144202afb9534cfbe54d591828868/twine/src/logger.ts#L90" target="_blank" rel="noreferrer">logger.ts:90</a></p><p>Builds <code>debug/log/{debug,info,warn,off}</code> - the commands a player runs to set (or clear) their own severity threshold. Call once, before anything that might call <a href="#for-1">for</a>&#39;s handles actually builds - order doesn&#39;t matter beyond that, since there is one objective, not one per namespace.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="dp-1" tabindex="-1">dp <a class="header-anchor" href="#dp-1" aria-label="Permalink to &quot;dp&quot;">​</a></h5><p><code>Datapack</code></p><h5 id="path" tabindex="-1">path? <a class="header-anchor" href="#path" aria-label="Permalink to &quot;path?&quot;">​</a></h5><p><code>string</code> = <code>&quot;debug/log&quot;</code></p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>void</code></p><hr><h3 id="attach" tabindex="-1">attach() <a class="header-anchor" href="#attach" aria-label="Permalink to &quot;attach()&quot;">​</a></h3><blockquote><p><code>static</code> <strong>attach</strong>(<code>instance</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/1f7cf8c4b76144202afb9534cfbe54d591828868/twine/src/logger.ts#L58" target="_blank" rel="noreferrer">logger.ts:58</a></p><p>Makes <code>instance</code> the target of the static <a href="#for-1">Logger.for</a>. Call once, before constructing anything whose functions might log - a module-level <code>const log = Logger.for(&quot;Name&quot;)</code> elsewhere is safe to import at any time (even before this runs) because its handles resolve Logger.current lazily, at the point they&#39;re actually called with a <code>ctx</code>, not at import time.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="instance" tabindex="-1">instance <a class="header-anchor" href="#instance" aria-label="Permalink to &quot;instance&quot;">​</a></h5><p><code>Logger</code></p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>void</code></p><hr><h3 id="for-1" tabindex="-1">for() <a class="header-anchor" href="#for-1" aria-label="Permalink to &quot;for()&quot;">​</a></h3><blockquote><p><code>static</code> <strong>for</strong>(<code>namespace</code>): <a href="./../interfaces/NamespaceLogger.html"><code>NamespaceLogger</code></a></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/1f7cf8c4b76144202afb9534cfbe54d591828868/twine/src/logger.ts#L67" target="_blank" rel="noreferrer">logger.ts:67</a></p><p>A namespaced handle callable at module scope, with no instance to thread through constructors - each method looks up <a href="#attach">Logger.attach</a>&#39;s instance when actually called, not when <code>for</code> itself is called.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="namespace-1" tabindex="-1">namespace <a class="header-anchor" href="#namespace-1" aria-label="Permalink to &quot;namespace&quot;">​</a></h5><p><code>string</code></p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><a href="./../interfaces/NamespaceLogger.html"><code>NamespaceLogger</code></a></p>',59)])])}const f=a(s,[["render",c]]);export{p as __pageData,f as default};
